/// <summary>
/// Binoculars disable vThirdPersonCamera so follow distance is not overwritten.
/// RotateCamera still updates internal yaw/pitch; apply that rotation directly to the live camera.
/// </summary>
private void ApplyBinocularDirectLook(float x, float y)
{
    if (cameraMain == null || tpCamera == null)
        return;

    tpCamera.RotateCamera(x, y);

    float pitch = tpCamera.mouseY;
    float yaw = tpCamera.mouseX;
    if (tpCamera.lerpState != null)
        pitch = vExtensions.ClampAngle(pitch, tpCamera.lerpState.yMinLimit, tpCamera.lerpState.yMaxLimit);

    cameraMain.transform.rotation = Quaternion.Euler(pitch, yaw, 0f);
}

